 const dir=path.join(out,spec.name);fs.mkdirSync(dir,{recursive:true});const context=await browser.newContext({viewport:{width:1440,height:1100},acceptDownloads:true}),page=await context.newPage();page.on('pageerror',e=>errors.push({page:spec.name,message:e.message}));if(spec.baseline)await page.route('**/baseline/kaopu-skin-workbench/src/app.js',route=>route.fulfill({body:fs.readFileSync(path.join(root,spec.folder,'src/app.js'),'utf8')+cameraHook,contentType:'text/javascript'}));
